// Campus model used by the Legacy dashboard. campus-v2.glb is generated by
// scripts/campus-model (bun run model:build) in uni.glb's scene frame, so both files work with
// CityModel's BLD_* selection and the traffic simulation. `?model=uni` shows the original model.
export const CAMPUS_MODEL_URLS = Object.freeze({
  detailed: "/campus-v2.glb",
  original: "/uni.glb",
});

export function resolveCampusModelUrl(search = globalThis.location?.search ?? "") {
  const requested = new URLSearchParams(search).get("model");
  return requested === "uni" || requested === "original" ? CAMPUS_MODEL_URLS.original : CAMPUS_MODEL_URLS.detailed;
}

export const CAMPUS_MODEL_URL = resolveCampusModelUrl();
